def get_structure(name: str) -> str:
    """Get XYZ structure string by name."""
    structures = {
        'cu111': CU_111_SURFACE,
        'co': CO_MOLECULE,
        'h2o': H2O_MOLECULE,
        'ch4': CH4_MOLECULE,
        'nh3': NH3_MOLECULE,
        'o2': O2_MOLECULE,
        'co_on_cu111': CO_ON_CU111,
    }
    return structures.get(name.lower(), '')


def save_structure(name: str, path: str):
    """Save XYZ structure to file."""
    content = get_structure(name)
    if content:
        with open(path, 'w') as f:
            f.write(content)
